{"type":"item.completed","item":{"id":"item_3","type":"command_execution","command":""C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command 'Get-Content -LiteralPath src/slugify.js,src/truncate.js,src/wordCount.js,src/index.js,README.md -Raw; git status --short; git diff --check; git diff -- README.md src/index.js'","aggregated_output":"/** Convert a string into a lowercase URL-safe slug. */
export function slugify(value) {
  if (typeof value !== "string") throw new TypeError("slugify expects a string");

  return value
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

/** Shorten a string to a maximum length, reserving space for an ellipsis. */
export function truncate(value, maxLength) {
  if (typeof value !== "string") throw new TypeError("truncate expects a string");
  return value.length <= maxLength ? value : `${value.slice(0, maxLength - 3)}...`;
}

/** Return the number of whitespace-separated words in a string. */
export function wordCount(value) {
  if (typeof value !== "string") throw new TypeError("wordCount expects a string");

  const trimmed = value.trim();
  return trimmed === "" ? 0 : trimmed.split(/\s+/).length;
}

